select
    user_id
    ,lower(if(edt_string_type = '', 'no_edt', coalesce(edt_string_type, 'no_edt'))) as edt_string_type
    ,coalesce(cast(is_ads as string), 'false') as is_ads
    ,feature_detail
    ,target_type

    ,operation
    ,operation_cnt
    ,place_order_gmv
    ,pc2_gmv

