--sql_divide_splitter--
create temporary view dwd_filtered_${grass_region_without_quote} as
select
    user_id
    ,is_ads
    ,feature_detail
    ,target_type
    ,filter(scenario_tags,
        value -> value in (
            'DA_Cart_Unify', 'DA_Daily Discover', 'DA_You May Also Like', 'DA_Cart Recommendation',
            'DA_mpp_ymal-order_list', 'DA_odp_ymal-order_detail', 'DA_Order Successful Recommendation',
            'DA_Me YMAL', 'DA_Shop YMAL', 'DA_Buy Again (Me Page)', 'DA_YMAL_Cart', 'DA_RCMD Unify',
            'dpm reporting object you may also like module User Scenario business line Rcmd',
            'dpm reporting object post purchase module User Scenario business line Rcmd',
            'dpm module Daily Discover business line Homepage',
            'dpm module Private Domin business line Rcmd'
        )
    ) as scenario_tags
    ,case
        when 
            edt_string_type in ('hari ini', 'today', 'chega hoje', 'hôm nay', 'วันนี้', '今天')
            or edt_string_type like '%jam%'
            or edt_string_type like '%hours%'
            or edt_string_type like '%hari ini%'
            or edt_string_type like '%today%'
            then 'a.today'
        when 
            edt_string_type in ('chega amanhã', 'ngày mai', 'พรุ่งนี้', 'esok', '明天')
            or edt_string_type like '%besok%'
            or edt_string_type like '%tomorrow%'
            then 'b.tomorrow'
        when edt_string_type = 'no_edt' or regexp_extract(edt_string_type, '([0-9]+)') = '' -- such as pre-order in search
            then 'd.no_edt'
        else 'c.days'
    end as edt_category
    ,edt_string_type

    ,operation
    ,operation_cnt
    ,place_order_gmv
    ,pc2_gmv
from
    dwd_concat_data_${grass_region_without_quote}
;

--sql_divide_splitter--
cache table base_table_${grass_region_without_quote} options('storageLevel'='DISK_ONLY') as
select
    user_id
    ,is_ads
    ,feature_detail
    ,target_type
    ,scenario_tags
    ,edt_category
    ,case 
        when edt_category = 'c.days' then cast(regexp_extract(edt_string_type, '([0-9]+)') as int)
        else -999 
    end as edt_min
    ,case 
        when edt_category = 'c.days' then cast(element_at(regexp_extract_all(edt_string_type, '([0-9]+)'), cardinality(regexp_extract_all(edt_string_type, '([0-9]+)'))) as int)
        else -999 
    end as edt_max
    ,sum(case when operation = 'impression' then operation_cnt else 0 end) as imp_cnt
    ,sum(case when operation = 'click' then operation_cnt else 0 end) as click_cnt
    ,sum(case when operation = 'order' then operation_cnt else 0 end) as order_cnt
    ,sum(case when operation = 'order' then place_order_gmv else 0 end) as gmv
    ,sum(case when operation = 'order' then pc2_gmv else 0 end) as pc2_gmv
from 
    dwd_filtered_${grass_region_without_quote}
group by 1, 2, 3, 4, 5, 6, 7, 8
;

